/**
 * Render the shortcut design artwork at its supplied size.
 * @param props - glyph kind and semantic color class.
 * @returns an ornamental SVG hidden from assistive technology.
 */
export function ShortcutIcon({ kind, className }: { kind: keyof typeof artwork; className?: string | undefined }) {
  const size = kind === 'edit' ? 12 : 16
  return <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} fill="currentColor" className={className} aria-hidden="true">{artwork[kind]}</svg>
}
